#!/usr/bin/env python3
"""Compute ground truth for CSX-323_Q1 from local CSX-323 package files."""

from __future__ import annotations

import csv
import json
import re
from datetime import date
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-323_Q1"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if self.skip_depth:
            return
        stripped = data.strip()
        if stripped:
            self.parts.append(stripped)

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def clean_text(text: str) -> str:
    replacements = {
        "\u00a0": " ",
        "\u2018": "'",
        "\u2019": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u2013": "-",
        "\u2014": "-",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    text = unescape(text)
    text = text.encode("ascii", errors="ignore").decode("ascii")
    return re.sub(r"\s+", " ", text).strip()


def load_json(package_dir: Path, relative_path: str) -> Any:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_html_text(package_dir: Path, relative_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package_dir / relative_path).read_text(encoding="utf-8", errors="ignore"))
    return clean_text(parser.text())


def inclusive_days(start_iso: str, end_iso: str) -> int:
    start = date.fromisoformat(start_iso)
    end = date.fromisoformat(end_iso)
    return (end - start).days + 1


def count_files(package_dir: Path) -> tuple[int, dict[str, int]]:
    with (package_dir / "metadata" / "files.csv").open("r", encoding="utf-8-sig", newline="") as handle:
        rows = list(csv.DictReader(handle))
    counts: dict[str, int] = {}
    for row in rows:
        category = row["data_category"]
        counts[category] = counts.get(category, 0) + 1
    return len(rows), counts


def count_occurrences(text: str, patterns: list[str]) -> int:
    total = 0
    for pattern in patterns:
        total += len(re.findall(pattern, text, flags=re.IGNORECASE))
    return total


def osm_counts(elements: list[dict[str, Any]]) -> dict[str, int]:
    counts = {"elements": 0, "amenities": 0, "critical_amenities": 0, "buildings": 0, "roads": 0}
    critical = {"hospital", "clinic", "doctors", "school", "police", "fire_station", "shelter"}
    for element in elements:
        counts["elements"] += 1
        tags = element.get("tags", {})
        amenity = tags.get("amenity")
        if amenity:
            counts["amenities"] += 1
            if amenity in critical:
                counts["critical_amenities"] += 1
        if "building" in tags:
            counts["buildings"] += 1
        if "highway" in tags:
            counts["roads"] += 1
    return counts


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / "CSX-323"

    event_path = "metadata/event.json"
    anchor_path = "data/event_reports/event_reports_003_Locked_event_anchor_2013-2016_Northeast_Pacific_marine_heatwave_The_Blob.json"
    wiki_search_path = "data/other/other_002_01_event_specific_wikipedia_search_Wikipedia_search_for_exact_event_name.json.json"

    event = load_json(package_dir, event_path)
    anchor = load_json(package_dir, anchor_path)
    wiki_search = load_json(package_dir, wiki_search_path)
    window = anchor["temporal_window"]
    event_window_days = inclusive_days(window["start_date"], window["end_date"])
    event_window_years = round(event_window_days / 365.0, 2)
    source_result_count = int(wiki_search["query"]["searchinfo"]["totalhits"])

    snippets = [
        clean_text(result.get("title", "") + " " + result.get("snippet", ""))
        for result in wiki_search.get("query", {}).get("search", [])
    ]
    snippet_text = " ".join(snippets)

    marine_heatwave_term_count = count_occurrences(
        " ".join([event["event_name"], event["hazard_family"], event["hazard_label"], snippet_text]),
        [r"marine heatwave", r"\bBlob\b", r"warm Blob"],
    )
    ecosystem_impact_term_count = count_occurrences(
        snippet_text,
        [r"ecological impacts?", r"toxic algal bloom", r"harmful algal bloom", r"algal blooms?", r"food[- ]web"],
    )
    northeast_pacific_reference_count = count_occurrences(
        " ".join([event["event_name"], event["region"], snippet_text]),
        [r"Northeast Pacific", r"Northeastern Pacific", r"northeast Pacific", r"Pacific Ocean"],
    )

    hazard_family_score = 1.0 if event["hazard_family"] == "marine_heatwave_coastal_ecosystem" else 0.0
    duration_score = min(event_window_days / 365.0, 3.0) / 3.0
    marine_term_score = min(marine_heatwave_term_count / 5.0, 1.0)
    ecosystem_context_score = min(ecosystem_impact_term_count / 2.0, 1.0)
    basin_context_score = min(northeast_pacific_reference_count / 2.0, 1.0)

    priority_index = round(
        0.25 * hazard_family_score
        + 0.20 * duration_score
        + 0.20 * marine_term_score
        + 0.20 * ecosystem_context_score
        + 0.15 * basin_context_score,
        2,
    )

    if (
        hazard_family_score
        and event_window_days > 365
        and marine_heatwave_term_count >= 3
        and ecosystem_impact_term_count >= 1
        and northeast_pacific_reference_count >= 1
    ):
        answer = "basin_scale_marine_heatwave_ecosystem_heat_stress_priority"
        impact_chain = [
            "persistent_ocean_heat_anomaly",
            "basin_scale_marine_heatwave",
            "marine_ecosystem_heat_stress_and_foodweb_disruption_priority",
        ]
    else:
        answer = "insufficient_evidence_for_priority"
        impact_chain = ["mixed_signal", "uncertain_mechanism", "additional_review_needed"]

    result = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": TASK_ID,
        "event_id": "CSX-323",
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "primary_gt": {
            "answer": answer,
            "priority_index": priority_index,
            "key_metrics": {
                "event_window_days": event_window_days,
                "event_window_years": event_window_years,
                "source_result_count": source_result_count,
                "marine_heatwave_term_count": marine_heatwave_term_count,
                "ecosystem_impact_term_count": ecosystem_impact_term_count,
                "northeast_pacific_reference_count": northeast_pacific_reference_count,
            },
            "impact_chain": impact_chain,
        },
        "key_values": {
            "event_window_days": event_window_days,
            "event_window_years": event_window_years,
            "source_result_count": source_result_count,
            "marine_heatwave_term_count": marine_heatwave_term_count,
            "ecosystem_impact_term_count": ecosystem_impact_term_count,
            "northeast_pacific_reference_count": northeast_pacific_reference_count,
            "priority_index": priority_index,
            "impact_chain": impact_chain,
            "judge_anchors": [
                "The event should be framed as a basin-scale marine heatwave and marine ecosystem heat-stress priority.",
                "The 1127-day window supports persistence rather than a short-duration weather-triggered disaster.",
                "Local event-search evidence links The Blob to marine heatwave persistence and ecological or harmful-algal-bloom impacts.",
                "The answer should avoid unsupported exact mortality, fishery-loss, climate-attribution, or direct urban infrastructure claims.",
            ],
        },
        "supporting_metrics": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "hazard_label": event["hazard_label"],
            "region": event["region"],
            "event_window": window,
            "wiki_search_totalhits": source_result_count,
            "component_scores": {
                "hazard_family_score": hazard_family_score,
                "duration_score": round(duration_score, 4),
                "marine_term_score": round(marine_term_score, 4),
                "ecosystem_context_score": round(ecosystem_context_score, 4),
                "basin_context_score": round(basin_context_score, 4),
            },
            "local_text_flags": {
                "wiki_search_has_the_blob_page": any("The Blob (Pacific Ocean)" in snippet for snippet in snippets),
                "wiki_search_has_marine_heatwave": bool(re.search(r"marine heatwave", snippet_text, flags=re.IGNORECASE)),
                "wiki_search_has_ecosystem_impact": ecosystem_impact_term_count > 0,
                "wiki_search_has_northeast_pacific_context": northeast_pacific_reference_count > 0,
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                event_path,
                anchor_path,
                wiki_search_path,
            ],
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Priority label",
                    "points": 4,
                    "description": "Selects basin_scale_marine_heatwave_ecosystem_heat_stress_priority.",
                    "partial_credit": "2 points for a marine heatwave label that omits the ecosystem heat-stress priority.",
                },
                {
                    "name": "Duration and scale",
                    "points": 3,
                    "description": "Uses the 1127-day multi-year window and basin-scale Northeast Pacific framing.",
                    "partial_credit": "1.5 points for identifying persistence without the correct duration.",
                },
                {
                    "name": "Heat-stress mechanism",
                    "points": 4,
                    "description": "Uses marine heatwave, Northeast Pacific, and ecological-impact terminology to justify ecosystem heat-stress priority.",
                    "partial_credit": "2 points for using marine heatwave terminology without clearly tying it to ecosystem impacts.",
                },
                {
                    "name": "Structured metrics",
                    "points": 3,
                    "description": "Reports priority_index near 1.00 and the expected event-window and text-evidence metrics with reasonable rounding.",
                    "partial_credit": "Award up to 0.5 points for each correct key metric, capped at 3.",
                },
                {
                    "name": "Competing-signal rejection",
                    "points": 3,
                    "description": "Rejects rainfall, wind, terrestrial burn or vegetation loss, and urban exposure as primary framings without relying on land-product proxies.",
                    "partial_credit": "Award 0.75 points for each correctly rejected competing framing.",
                },
                {
                    "name": "Impact-chain quality",
                    "points": 2,
                    "description": "Gives the chain from persistent ocean heat anomaly to basin-scale marine heatwave to ecosystem heat stress and food-web disruption.",
                    "partial_credit": "1 point for a partially correct two-step chain.",
                },
                {
                    "name": "Overclaim control",
                    "points": 1,
                    "description": "Avoids unsupported exact mortality, fisheries-loss, attribution, or direct urban-infrastructure claims.",
                    "partial_credit": "0.5 points for one minor overclaim that does not change the main diagnosis.",
                },
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(result, handle, ensure_ascii=True, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
